    let { f: factor } = factorOf(ev.info);
    let step = cholSolve(factor, ev.score);
    const score = ev.score.reduce((acc, u, i) => acc + u * step[i], 0);
    const warnings = [];
    // the coefficients accepted at each iteration (0: the start), for the iterations-ran-out case below
    const accepted = [beta];
    let best = ev.loglik;
    let next = beta.map((b, i) => b + step[i]);
